/*
 * CryNet — model component implementation.
 *
 * This is the single translation unit that includes the notebook-generated
 * model_data.h. Keeping the include here means the generated byte array
 * has exactly one definition in the firmware image.
 */

#include "model_data.h"   /* generated by the training notebook — do not edit */
#include "crynet_model.h"

const uint8_t *crynet_model_bytes(void)
{
    return (const uint8_t *)crynet_model;
}

size_t crynet_model_size(void)
{
    return (size_t)crynet_model_len;
}
